package com.example.arcana.client;
import com.example.arcana.network.*; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.components.Button; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component;
public class SkillTreeScreen extends Screen { public SkillTreeScreen(){super(Component.literal("Arcana Skill Tree"));} protected void init(){int x=width/2-105;addRenderableWidget(Button.builder(Component.literal("Attunement I  +10 Mana"),b->ArcanaNetwork.CHANNEL.sendToServer(new UpgradeSkillPacket("attunement"))).bounds(x,height/2-55,210,20).build());addRenderableWidget(Button.builder(Component.literal("Arcane Bolt  +8 Range"),b->ArcanaNetwork.CHANNEL.sendToServer(new UpgradeSkillPacket("bolt_range"))).bounds(x,height/2-25,210,20).build());addRenderableWidget(Button.builder(Component.literal("Blink Branch  Coming Next"),b->{}).bounds(x-115,height/2+20,100,20).build());addRenderableWidget(Button.builder(Component.literal("Ward Branch  Coming Next"),b->{}).bounds(x+115,height/2+20,100,20).build());} public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g);g.drawCenteredString(font,title,width/2,25,0xE8D5FF);g.drawCenteredString(font,"Spend one skill point per node upgrade",width/2,45,0xC0A8DD);g.drawCenteredString(font,"Core",width/2,90,0xFFFFFF);g.drawCenteredString(font,"Exploration",width/2-165,height/2+5,0x8FE7FF);g.drawCenteredString(font,"Defense",width/2+165,height/2+5,0xA8F0B2);super.render(g,mx,my,pt);}}
